fn prepare(){
 assert!(!r("plan.json").exists());assert_eq!(read(r("native/result.json"))["status"],"complete");
 let core=fs::read_to_string(r("native/core-tests/stdout.log")).unwrap();assert!(core.contains("test result: ok. 128 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out"));
 let log=fs::read_to_string(r("native/driver-build/stderr.log")).unwrap();let line=log.lines().find(|l|l.contains("Running")&&l.contains("--crate-name zopro_two_chain_stream")).unwrap();for f in["-C opt-level=3","-C lto=fat","-C codegen-units=1","-C target-cpu=native","--cfg zopro_two_chain_stream"]{assert!(line.contains(f));}
 let reference=read(r("reference-audit.json"));assert_eq!(reference["passed"],true);let old=reference["old_registry_packages"].as_object().unwrap();let new=reference["new_registry_packages"].as_object().unwrap();assert!(new.iter().all(|(k,v)|old.get(k)==Some(v)));save(r("reference-package-scope.json"),&json!({"all_new_registry_packages_match_frozen":true,"old_package_entries":old.len(),"new_package_entries":new.len(),"full_lock_package_maps_equal":old==new,"additional_old_lock_entries_retained":true}));
 let ids=read(r("identities.json"));for arm in["frozen","OFF","ON"]{assert_eq!(hash(ids[arm]["binary"].as_str().unwrap()),ids[arm]["binary_sha256"]);}assert_eq!(ids["OFF"],ids["ON"]);
 let mut env=read(r("environment.json"));for k in["RUSTFLAGS","RUSTC","CARGO_TARGET_DIR","CARGO_BUILD_JOBS"]{env.as_object_mut().unwrap().remove(k);}
 let cs=contexts();let mut steps=vec![];for c in&cs{for arm in["frozen","OFF","ON"]{steps.push(step(format!("preflight-{}-{arm}",c.0),args(c,arm,64)));}}
 steps.push(step("preflight-check".into(),vec![r("campaign").display().to_string(),"preflight".into()]));
 for b in 0..15{let mut order=(0..cs.len()).collect::<Vec<_>>();order.rotate_left(b%cs.len());if b%2==1{order.reverse();}for i in order{let c=&cs[i];let mut arms=["frozen","OFF","ON"];arms.rotate_left((b+i)%3);if b%2==1{arms.reverse();}for arm in arms{steps.push(step(format!("latency-{}-b{b:02}-{arm}",c.0),args(c,arm,4096)));}}}
 for d in["stat","perf"]{fs::create_dir(r(d)).unwrap();}for n in["ctl","ack"]{assert!(Command::new("mkfifo").arg(r(n)).status().unwrap().success());}
 let selected=cs.iter().filter(|c|c.1=="G2"&&c.3==32).collect::<Vec<_>>();for profile in[false,true]{for c in&selected{for arm in["frozen","OFF","ON"]{let name=format!("{}-{}-{arm}",if profile{"cycles"}else{"stat"},c.0);let mut penv=env.clone();penv["ZOPRO_BENCH_PERF_CTL"]=json!(r("ctl"));penv["ZOPRO_BENCH_PERF_ACK"]=json!(r("ack"));let mut argv=vec!["sudo".into(),"-n".into(),"env".into()];for(k,v)in penv.as_object().unwrap(){argv.push(format!("{k}={}",v.as_str().unwrap()));}argv.push("perf".into());if profile{argv.extend(["record".into(),"--no-buildid-cache".into(),"--sample-cpu".into(),"--timestamp".into(),"-P".into(),"-e".into(),"cycles:u".into(),"-c".into(),"16000000".into(),"-m".into(),"512".into(),"-o".into(),format!("{R}/perf/{name}.data")]);}else{argv.extend(["stat".into(),"--no-big-num".into(),"-x".into(),";".into(),"-e".into(),"{cycles:u,instructions:u,cache-misses:u,branch-misses:u}".into(),"-o".into(),format!("{R}/stat/{name}.csv")]);}argv.extend(["--delay=-1".into(),format!("--control=fifo:{R}/ctl,{R}/ack"),"--".into()]);argv.extend(args(c,arm,if profile{65536}else{16384}));let mut s=step(name,argv);s["environment"]=penv;steps.push(s);}}}
 for c in selected{for arm in["frozen","OFF","ON"]{let name=format!("cycles-{}-{arm}",c.0);let data=format!("{R}/perf/{name}.data");steps.push(step(format!("own-{name}"),vec!["sudo".into(),"-n".into(),format!("{R}/campaign"),"own".into(),data.clone()]));for meta in[false,true]{let mut argv=vec!["perf".into(),"script".into(),"--header".into(),"--ns".into(),"-i".into(),data.clone(),"-F".into(),"pid,tid,cpu,time,period,ip,sym".into()];if meta{argv.extend(["--show-mmap-events".into(),"--show-task-events".into(),"--show-lost-events".into()]);}steps.push(step(format!("{}-{name}",if meta{"metadata"}else{"decode"}),argv));}steps.push(step(format!("events-{name}"),vec!["perf".into(),"evlist".into(),"-v".into(),"-i".into(),data.clone()]));steps.push(step(format!("loss-{name}"),vec![format!("{R}/campaign"),"loss".into(),data]));}}
 for s in&mut steps{if s.get("environment").is_none(){s["environment"]=env.clone();}}assert_eq!(steps.len(),475);
 let mut files=vec![];for d in["source","driver","native"]{walk(&r(d),&mut files);}for f in["setup.rs","design.md","protocol.md","tests.rs","two-chain-apply.rs","g1-caller.rs","g2-caller.rs","source-audit.json","environment.json","build-plan.json","build-pins.json","freeze.rs","reference-audit.rs","reference-audit.json","reference-package-scope.json","identities.json","capture-prepare.rs","make-campaign.rs","campaign.rs","campaign","control-bin","candidate-bin"]{files.push(r(f));}for f in["pins.json","control-bin","build-control.log","control/Cargo.lock","g1-caller.rs","g2-caller.rs","driver.rs"]{files.push(Path::new("/home/ubuntu/src/zopro-perf-work/g2-denominator-tree176").join(f));}files.push(X.into());let pins=files.into_iter().map(|p|(p.display().to_string(),hash(p))).collect::<BTreeMap<_,_>>();save(r("pins.json"),&json!(pins));save(r("plan.json"),&json!({"version":1,"source_pins":r("pins.json"),"steps":steps}));println!("Prepared475capturecommands/444callers;exact frozen+samebinaryOFF/ON;no recording yet.");
}
fn preflight(){let mut count=0;for c in contexts(){let mut h=None;let mut caps=None;for arm in["frozen","OFF","ON"]{let n=format!("preflight-{}-{arm}",c.0);let v=caller(&n);let e=read(r(format!("runs/{n}/exit.json")));assert_eq!(e["success"],true);assert_eq!(v["complete_generator_oracle"],true);assert_eq!(v["timed_allocations"],0);assert_eq!(v["rounds_per_worker"],64);assert_eq!(v["kind"],c.1);assert_eq!(v["size"],c.2);assert_eq!(v["workers"],c.3);if let Some(w)=&h{assert_eq!(&v["output_sha256"],w);}else{h=Some(v["output_sha256"].clone());}if let Some(w)=&caps{assert_eq!(&v["scratch_capacity_bytes_by_worker"],w);}else{caps=Some(v["scratch_capacity_bytes_by_worker"].clone());}count+=1;}}assert_eq!(count,27);println!("All27preflights match independentwhole-generator oracles/cross-armhashes/capacities;zero timedallocs.");}
